Diagnostic tests:
{"laboratory_examinations": [{"changes_over_time": "Not specified", "date": "Not specified", "findings": "Genetic testing showed a heterozygous mutation in exon 15 of the NSD1 gene [c.5146G>A, p.(Gly1716Arg)], classified as pathologic in Leiden Open Variation Database (LOVD) and not found in The Genome Aggregation Database (gnomAD).", "procedure_name": "Genetic testing"}], "other_examinations": [{"changes_over_time": "Not specified", "date": "Not specified", "findings": "Prolonged (62 h) non-invasive video-EEG monitoring showed symmetrical and slightly disorganized base activity, with 778 bilateral interictal epileptic discharges (84.1% in the left anterior temporal region and 15.9% in the right anterior temporal region). Six electroclinical seizures were recorded: five focal onset impaired awareness motor seizures during the awake period and one during sleep. All recorded seizures had the ictal onset and symptomatogenic area in the left temporal lobe.", "procedure_name": "Video-EEG monitoring"}, {"changes_over_time": "Not specified", "date": "Not specified", "findings": "Neuropsychological testing found low scores in episodic memory (verbal and non-verbal), language, speech, constructive praxis, and working memory.", "procedure_name": "Neuropsychological testing"}, {"changes_over_time": "Not specified", "date": "Not specified", "findings": "Pre-operative score was 45.4.", "procedure_name": "Quality of Life in Epilepsy Inventory-31 (QOLIE-31)"}], "radiographic_examinations": [{"changes_over_time": "Not specified", "date": "Not specified", "findings": "Brain MRI showed left hippocampus atrophy and right hippocampus malrotation.", "procedure_name": "Brain MRI"}]}

