Diagnostic tests:
{"laboratory_examinations": [{"changes_over_time": "Trio sequencing at 2 years and 5 months revealed a compound heterozygous variant of the ACTL6B gene.", "date": "5 months", "findings": "No pathogenic variants found that were extremely consistent with the phenotype.", "procedure_name": "Whole-exome sequencing, copy number variation, and mitochondrial gene testing"}, {"changes_over_time": "Not specified.", "date": "2 years and 5 months", "findings": "Compound heterozygous variant of the ACTL6B gene: a heterozygous deletion of exons 1-4 inherited from the father, and a c.1017 + 3G > T mutation in the intron region inherited from the mother.", "procedure_name": "Trio sequencing using whole-exon next-generation sequencing (NGS)"}], "other_examinations": [{"changes_over_time": "At 8 months: extensive, multifocal epileptic discharges between seizures; at 1 year and 2 months: slow background activity, no occipital-dominated rhythm, interictal multifocal epileptiform discharges; at 1 year and 6 months: no occipital dominant rhythm, bilateral occipital spikes, slow waves, no seizures detected.", "date": "1 month and 15 days after birth", "findings": "Interictal multifocal epileptiform discharges, noticeable bilaterally in the occipital region.", "procedure_name": "Video electroencephalogram (VEEG)"}, {"changes_over_time": "Not specified.", "date": "8 months", "findings": "Extensive, multifocal epileptic discharges between seizures.", "procedure_name": "Video electroencephalogram (VEEG)"}, {"changes_over_time": "Not specified.", "date": "1 year and 2 months", "findings": "Slow background activity, no occipital-dominated rhythm, interictal multifocal epileptiform discharges.", "procedure_name": "Video electroencephalogram (VEEG)"}, {"changes_over_time": "Not specified.", "date": "1 year and 6 months", "findings": "No occipital dominant rhythm, bilateral occipital spikes, slow waves, no seizures detected.", "procedure_name": "Video electroencephalogram (VEEG)"}], "radiographic_examinations": [{"changes_over_time": "At 6 months: deep sulci, delayed myelination, little white matter, and thin corpus callosum; brain atrophy observed at 2 years and 10 months.", "date": "27th day after birth", "findings": "Blurred T1 high signal in the hindlimb of the internal capsule, lack of white matter, high T2 signal.", "procedure_name": "Brain MRI"}, {"changes_over_time": "Not specified.", "date": "6 months", "findings": "Deep sulci, delayed myelination, little white matter, and thin corpus callosum.", "procedure_name": "Brain MRI"}, {"changes_over_time": "Not specified.", "date": "2 years and 10 months", "findings": "Demonstrated brain atrophy.", "procedure_name": "Brain CT"}]}

