{"laboratory_examinations": [{"changes_over_time": "Not specified", "date": "Not specified", "findings": "There were no remarkable laboratory tests, suggesting the absence of rheumatoid arthritis.", "procedure_name": "Initial Test Results"}], "other_examinations": [{"changes_over_time": "Not specified", "date": "Postoperative day 21", "findings": "The ROM was 10\u00b0-110\u00b0; HKAa of valgus 16\u00b0 on the right knee and 16\u00b0 on the left knee.", "procedure_name": "Postoperative ROM Assessment"}, {"changes_over_time": "Decreased ROM from 10\u00b0-110\u00b0 at postoperative day 21 to 5\u00b0-125\u00b0.", "date": "1 year follow-up", "findings": "The knee ROM was 5\u00b0-125\u00b0; HKAa of valgus 13\u00b0 on the right knee and 17\u00b0 on the left knee.", "procedure_name": "1-Year Follow-Up ROM Assessment"}, {"changes_over_time": "No significant change in ROM compared to the 1-year follow-up; HKAa improved from 13\u00b0 to 11\u00b0 on the right knee.", "date": "Annual follow-up", "findings": "Fixed-knee ROM (10\u00b0-125\u00b0); HKAa of valgus 11\u00b0 on the right knee and 16\u00b0 on the left knee.", "procedure_name": "Annual Follow-Up ROM Assessment"}, {"changes_over_time": "Improved ROM from 10\u00b0-125\u00b0 at the annual follow-up to 10\u00b0-135\u00b0.", "date": "5 years follow-up", "findings": "The ROM of the affected knee was 10\u00b0-135\u00b0 with an extension lag of 10\u00b0; HKAa of valgus 11\u00b0 on the right knee and 17\u00b0 on the left knee.", "procedure_name": "5-Year Follow-Up ROM Assessment"}, {"changes_over_time": "Improved from 20/30 preoperatively to 60/50 postoperatively on the right knee and from 60/60 preoperatively to 85/85 on the left knee at the latest follow-up.", "date": "Not specified", "findings": "Preoperative knee score was 20/30, and functional score was 60/60 on the right and left knees, respectively; improved to 60/50 and 85/85 on the right and left knees, respectively, at 5 years.", "procedure_name": "Knee Society Knee score and Function score assessment"}, {"changes_over_time": "Not specified.", "date": "Not specified", "findings": "Manual muscle testing showed grade 3/4 on both knees, range of motion (ROM) was 20\u00b0-150\u00b0, patella was laterally dislocated during knee flexion.", "procedure_name": "Physical examination"}], "radiographic_examinations": [{"changes_over_time": "Postoperative day 21: HKAa of valgus 16\u00b0 on the right and left knees. At 1-year follow-up: HKAa of valgus 13\u00b0 (right) and 17\u00b0 (left). Annual follow-up: HKAa of valgus 11\u00b0 (right) and 16\u00b0 (left). Latest follow-up (5 years): HKAa of valgus 11\u00b0 (right) and 17\u00b0 (left).", "date": "Not specified", "findings": "Severe genu valgum of the right knee with a hip-knee-ankle angle (HKAa) of valgus 29.0\u00b0, grade IV osteoarthritic changes in the lateral femorotibial compartment according to the Kellgren-Lawrence classification, and laterally dislocated patella.", "procedure_name": "long-leg anteroposterior weight-bearing radiographs"}, {"changes_over_time": "Not specified.", "date": "Not specified", "findings": "Tibial tuberosity to trochlear groove distance of 41.3 mm.", "procedure_name": "Computed tomography of the knee"}, {"changes_over_time": "Not specified.", "date": "Not specified", "findings": "Dysplasia of the trochlea with a sulcus angle of 150\u00b0 and laterally located patella.", "procedure_name": "skyline view radiographs"}]}

